mapper.select:
select

from cere_platform_shop
where shop_id = #{shopId,jdbcType=BIGINT}

SELECT ANY_VALUE(a.shop_id) as shop_id, ANY_VALUE(d.shop_name) as shop_name, a.product_id, ANY_VALUE(a.product_name) as product_name, ANY_VALUE(c.product_image) as image, ANY_VALUE(b.sku_id) as sku_id, ANY_VALUE(b.original_price) as original_price, ANY_VALUE(b.price) as price, ANY_VALUE(ifnull(f.number, 0) + a.fictitious_number) as number, ANY_VALUE(a.product_brief) as product_brief, 0 as activityType from cere_shop_product a LEFT JOIN (SELECT a.product_id,ANY_VALUE(a.price) as price,ANY_VALUE(a.sku_id) as sku_id,ANY_VALUE(a.price) as original_price from cere_product_sku a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id) b ON a.product_id=b.product_id LEFT JOIN (SELECT a.product_id,ANY_VALUE(a.product_image) as product_image from cere_product_image a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id) c ON a.product_id=c.product_id LEFT JOIN cere_platform_shop d ON a.shop_id=d.shop_id LEFT JOIN cere_product_classify e ON a.classify_id=e.classify_id LEFT JOIN cere_shop_group sg ON a.shop_group_id = sg.shop_group_id LEFT JOIN (SELECT SUM(a.number) number, a.sku_id, ANY_VALUE(a.order_id) as order_id from cere_order_product a, cere_shop_order b where a.order_id=b.order_id and b.state in(2,3,4) GROUP BY sku_id) f ON b.sku_id=f.sku_id where a.shop_id=#{shopId} and a.shelve_state=1 and d.state=1
and a.product_name like concat('%',#{search},'%')
and a.classify_id1 = #{classifyId}
and a.classify_id2 = #{classifyId}
and a.classify_id3 = #{classifyId}
and ( a.classify_id1 = #{classifyId} OR a.classify_id2 = #{classifyId} OR a.classify_id3 = #{classifyId} )
and sg.shop_group_id = #{groupId}
and price>=#{minMoney}
and price<=#{maxMoney}
GROUP BY a.product_id ORDER BY
price,
price DESC,
f.number,
f.number DESC,
a.update_time DESC,a.create_time DESC

SELECT a.product_id, ANY_VALUE(a.product_name) as product_name, ANY_VALUE(c.product_image) as image, ANY_VALUE(b.sku_id) as sku_id, ANY_VALUE(f.number) as number, ANY_VALUE(a.shop_id) as shop_id, ANY_VALUE(a.product_brief) as product_brief, ANY_VALUE(b.original_price) as original_price, ANY_VALUE(b.price) as price, 0 as activityType from cere_shop_product a LEFT JOIN (SELECT a.product_id,ANY_VALUE(a.price) as price,ANY_VALUE(a.sku_id) as sku_id,ANY_VALUE(a.price) as original_price from cere_product_sku a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id) b ON a.product_id=b.product_id LEFT JOIN (SELECT a.product_id,ANY_VALUE(a.product_image) as product_image from cere_product_image a,cere_shop_product b where a.product_id=b.product_id GROUP BY a.product_id) c ON a.product_id=c.product_id LEFT JOIN cere_platform_shop d ON a.shop_id=d.shop_id LEFT JOIN (SELECT SUM(a.number) number, a.sku_id, ANY_VALUE(a.order_id) as order_id from cere_order_product a, cere_shop_order b where a.order_id=b.order_id and b.state in(2,3,4) GROUP BY sku_id) f ON b.sku_id=f.sku_id where a.shop_id=#{shopId}
and a.shelve_state = #{shelveState}
and b.price>=#{minMoney}
and b.price<=#{maxMoney}
GROUP BY a.product_id ORDER BY
price,
price DESC,
f.number,
f.number DESC,
a.update_time DESC,a.create_time DESC limit 10

SELECT d.shop_id, d.shop_name, d.shop_logo from cere_platform_shop d where d.state=1 and d.shop_id IN(
#{i.shopId}
)
